<?php $page='dashboard';$title='Dashboard';require_once __DIR__.'/includes/functions.php';require_login();$uid=$_SESSION['user_id'];$t=get_totals($pdo,$uid);$bq=$pdo->prepare("SELECT * FROM budgets WHERE user_id=? AND period='monthly' ORDER BY start_date DESC,id DESC LIMIT 1");$bq->execute([$uid]);$budget=(float)($bq->fetch()['amount']??0);$remaining=$budget-$t['expense'];$recent=$pdo->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY transaction_date DESC,id DESC LIMIT 6');$recent->execute([$uid]);$cats=$pdo->prepare("SELECT category,SUM(amount) total FROM transactions WHERE user_id=? AND type='expense' GROUP BY category ORDER BY total DESC");$cats->execute([$uid]);$catRows=$cats->fetchAll();$max=max(array_column($catRows,'total')?:[1]);require 'includes/header.php';?>
<div class="hero"><h1>Hello, <?=e(current_user_name())?>! 👋</h1><p>Take control of your money. Plan your budget, track expenses, and build a better future.</p></div><div class="grid"><div class="card"><div class="stat-label">↗ Total Income</div><div class="stat-value"><?=money($t['income'])?></div></div><div class="card"><div class="stat-label">↘ Total Expenses</div><div class="stat-value"><?=money($t['expense'])?></div></div><div class="card"><div class="stat-label">◎ Remaining Budget</div><div class="stat-value"><?=money($remaining)?></div></div><div class="card"><div class="stat-label">▥ Monthly Budget</div><div class="stat-value"><?=money($budget)?></div></div></div>
<div class="two-col"><div class="card"><h3>Expense Overview</h3><?php if(!$catRows):?><p class="empty">No expenses recorded yet.</p><?php else: foreach($catRows as $c):?><div class="bar-row"><small><?=e($c['category'])?> — <?=money($c['total'])?></small><div class="progress"><span style="width:<?=min(100,((float)$c['total']/$max)*100)?>%"></span></div></div><?php endforeach;endif;?></div><div class="card"><h3>Recent Transactions</h3><?php foreach($recent as $r):?><div class="list-item"><strong><?=e($r['description'])?> — <?=money($r['amount'])?></strong><div class="muted"><?=e(ucfirst($r['type']))?> · <?=e($r['category'])?> · <?=e($r['transaction_date'])?></div></div><?php endforeach;if(!$recent->rowCount()):?><p class="empty">No transactions yet.</p><?php endif;?></div><div class="card"><h3>Budget Progress</h3><div class="progress"><span style="width:<?= $budget>0?min(100,($t['expense']/$budget)*100):0 ?>%"></span></div><p><?= $budget>0?round(($t['expense']/$budget)*100):0 ?>% used</p></div><div class="card"><h3>Quick Actions</h3><div class="grid" style="grid-template-columns:1fr 1fr"><a class="btn secondary" href="expenses.php?action=add">＋ Add Expense</a><a class="btn secondary" href="income.php?action=add">↗ Add Income</a><a class="btn secondary" href="budget.php">◎ Set Budget</a><a class="btn secondary" href="reports.php">▥ View Reports</a></div></div></div><?php require 'includes/footer.php';?>
